package com.eventpulse.service;
import com.eventpulse.model.Event; import java.time.Clock; import java.time.Duration; import java.time.Instant;
public class ReminderService {private final EventService events;private final NotificationService notifications;private final Clock clock;public ReminderService(EventService e,NotificationService n){this(e,n,Clock.systemUTC());}public ReminderService(EventService e,NotificationService n,Clock c){events=e;notifications=n;clock=c;}public int sendReminder(String eventId,String reminderType){Duration offset=switch(reminderType){case "24h"->Duration.ofHours(24);case "1h"->Duration.ofHours(1);default->throw new IllegalArgumentException("Unsupported reminder type");};Event event=events.get(eventId);Instant now=clock.instant(),start=Instant.parse(event.getStartDateTime());if(!"UPCOMING".equals(event.getStatus())||!start.isAfter(now)||now.isBefore(start.minus(offset)))return 0;var results=notifications.announce(event,NotificationService.EVENT_REMINDER,"reminder:"+reminderType+":event-revision:"+event.getUpdatedAt());if(results.stream().anyMatch(r->"FAILED".equals(r.getStatus())))throw new IllegalStateException("One or more reminder notifications failed and may be retried");return (int)results.stream().filter(r->"ACCEPTED_BY_SES".equals(r.getStatus())).count();}}
